import{_ as n,o as r,c as t,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Prüfungsordnungen für Versetzung und Abschlüsse zuordnen","description":"","frontmatter":{},"headers":[],"relativePath":"zeugnisse/pruefungsordnungen.md","filePath":"zeugnisse/pruefungsordnungen.md"}'),u={name:"zeugnisse/pruefungsordnungen.md"};function a(i,e,h,d,g,l){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="prufungsordnungen-fur-versetzung-und-abschlusse-zuordnen" tabindex="-1">Prüfungsordnungen für Versetzung und Abschlüsse zuordnen <a class="header-anchor" href="#prufungsordnungen-fur-versetzung-und-abschlusse-zuordnen" aria-label="Permalink to &quot;Prüfungsordnungen für Versetzung und Abschlüsse zuordnen&quot;">​</a></h1><p>Wählen Sie vor einer Berechnung die zur Schulform, zum Bildungsgang und zur Laufbahn passende Prüfungsordnung. Ein Programmfeld oder ein erfolgreiches Rechenprotokoll ersetzt nicht die Prüfung dieser Zuordnung.</p><h2 id="schulform-und-bildungsgang" tabindex="-1">Schulform und Bildungsgang <a class="header-anchor" href="#schulform-und-bildungsgang" aria-label="Permalink to &quot;Schulform und Bildungsgang&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Maßgebliche Vorschrift</th></tr></thead><tbody><tr><td>Grundschule</td><td><a href="https://bass.schule.nrw/6181.htm" target="_blank" rel="noreferrer">AO-GS</a>, insbesondere § 7 zur Versetzung und § 8 zum Übergang</td></tr><tr><td>Sekundarstufe I</td><td><a href="https://bass.schule.nrw/12691.htm" target="_blank" rel="noreferrer">APO-S I</a>: schulformspezifische Versetzung nach §§ 22–29; Abschlüsse und Oberstufenberechtigung nach §§ 40–43</td></tr><tr><td>Gymnasiale Oberstufe</td><td><a href="https://bass.schule.nrw/9607.htm" target="_blank" rel="noreferrer">Bisherige APO-GOSt mit Verwaltungsvorschriften</a>; Kohortenabgrenzung unten beachten</td></tr></tbody></table><p>Für die Verfahren am Berufskolleg verwenden Sie den <a href="/zeugnisse/berufskolleg.html">eigenen Einstieg</a>. Dessen Bildungsgänge dürfen nicht pauschal nach den Regeln der allgemeinbildenden Oberstufe beurteilt werden.</p><h2 id="welche-apo-gost-gilt" tabindex="-1">Welche APO-GOSt gilt? <a class="header-anchor" href="#welche-apo-gost-gilt" aria-label="Permalink to &quot;Welche APO-GOSt gilt?&quot;">​</a></h2><p>Die <a href="https://bass.schule.nrw/20319.htm" target="_blank" rel="noreferrer">neue APO-GOSt von 2026</a> tritt am <strong>1. August 2027</strong> in Kraft. Nach ihrer Übergangsvorschrift in § 45 gilt sie erstmals für Schülerinnen und Schüler, die <strong>im Schuljahr 2027/28 die Einführungsphase besuchen</strong>. Die übrigen Schülerinnen und Schüler schließen nach der bisherigen Ordnung ab.</p><p>Die vorhandenen Anleitungen <a href="/zeugnisse/sekundarstufen.html">Abitur bearbeiten</a> beschreiben den bisherigen Ablauf mit vier Abiturfächern. Übertragen Sie künftige Bestimmungen nicht allein wegen ihres Veröffentlichungsdatums auf frühere Kohorten. Für Wiederholungen und Wechsel ist die individuelle Laufbahn anhand der Übergangsregel zuzuordnen.</p><h2 id="ergebnisse-prufen-und-ubernehmen" tabindex="-1">Ergebnisse prüfen und übernehmen <a class="header-anchor" href="#ergebnisse-prufen-und-ubernehmen" aria-label="Permalink to &quot;Ergebnisse prüfen und übernehmen&quot;">​</a></h2><p>Prüfen Sie Notenvollständigkeit, Sprachenfolge, Wiederholungen und die maßgeblichen Nachweise, bevor Sie Berechnungsergebnisse übernehmen. Bei <a href="/zeugnisse/versetzung.html">Versetzung und Abschnittswechsel</a> bleiben die fachliche Entscheidung und der technische Übertrag getrennte Arbeitsschritte. Für die ZP10 gelten zusätzlich die Hinweise zur <a href="/zeugnisse/zp10-rechtsstand.html">Notenbildung und mündlichen Prüfung</a>.</p>',10)])])}const f=n(u,[["render",a]]);export{c as __pageData,f as default};
